use vstd::prelude::*;

verus! {
    fn swap_first_and_last(a: &mut Vec<i32>)
        requires
            // the vector must be non‐empty
            a.len() > 0,
        ensures
            // the length is preserved
            a@.len() == old(a@).len(),
            // the new first element is the old last
            a@[0] == old(a@)[old(a@).len() - 1],
            // the new last element is the old first
            a@[old(a@).len() - 1] == old(a@)[0],
            // all the middle elements remain unchanged
            forall |i: nat|
                1 <= i && i < old(a@).len() - 1 ==>
                    a@[i] == old(a@)[i],
    {
        let len = a.len();
        // if there's only one element, swapping is a no‐op
        if len > 1 {
            let first = a[0];
            let last  = a[len - 1];
            a[0]        = last;
            a[len - 1]  = first;
        }
    }
}

fn main() {
    // example usage
    let mut v = Vec::from_slice(&[10, 20, 30, 40]);
    swap_first_and_last(&mut v);
    assert(v == Vec::from_slice(&[40, 20, 30, 10]));
}